    fn anchored_groups_have_no_candidates() {
        let rows = (0..10_000).map(|i| row(i, false)).collect::<Vec<_>>();
        assert!(bounded_candidates(&rows, &CandidateRule::ALL, 0).unwrap().is_empty());
    }
